package com.yongdrel.order_service.adapter.in.web;
import com.yongdrel.order_service.application.service.OrderApplicationService;
import org.springframework.beans.factory.annotation.Value; import org.springframework.http.*; import org.springframework.web.bind.annotation.*; import java.nio.charset.StandardCharsets; import java.security.MessageDigest; import java.util.*; import java.time.Instant;
@RestController @RequestMapping("/internal/orders") public class InternalOrderController{
 private final OrderApplicationService service; private final byte[] key; private final byte[] paymentKey;
 public InternalOrderController(OrderApplicationService s,@Value("${app.internal.scheduler-api-key}")String configured,@Value("${app.internal.payment-api-key}")String payment){if(configured==null||configured.isBlank()||payment==null||payment.isBlank())throw new IllegalStateException("Internal trust keys required");service=s;key=configured.getBytes(StandardCharsets.UTF_8);paymentKey=payment.getBytes(StandardCharsets.UTF_8);}
 @PostMapping("/{id}/expire") @ResponseStatus(HttpStatus.NO_CONTENT) public void expire(@PathVariable UUID id,@RequestHeader(value="X-Internal-API-Key",required=false)String provided,@RequestHeader("X-Tenant-Id")UUID tenant){if(provided==null||!MessageDigest.isEqual(key,provided.getBytes(StandardCharsets.UTF_8)))throw new org.springframework.web.server.ResponseStatusException(HttpStatus.UNAUTHORIZED,"Invalid scheduler credentials");service.fail(id,tenant);}
 @GetMapping("/{id}/ownership") public boolean ownership(@PathVariable UUID id,@RequestParam UUID userId,@RequestParam UUID tenantId,@RequestHeader(value="X-Internal-API-Key",required=false)String provided){auth(provided);return service.owns(id,userId,tenantId);}
 @GetMapping("/expired") public List<Expired> expired(@RequestParam Instant before,@RequestParam(defaultValue="100")int limit,@RequestHeader(value="X-Internal-API-Key",required=false)String provided){auth(provided);if(limit<1||limit>100)throw new org.springframework.web.server.ResponseStatusException(HttpStatus.BAD_REQUEST,"Invalid limit");return service.expired(before).stream().limit(limit).map(o->new Expired(o.getId(),o.getTenantId(),o.getCreatedAt())).toList();}
 @GetMapping("/{id}/payment-details") public PaymentDetails details(@PathVariable UUID id,@RequestParam(required=false) UUID tenantId,@RequestHeader(value="X-Internal-API-Key",required=false)String provided){auth(provided);return tenantId==null?service.paymentDetailsInternal(id):service.paymentDetails(id,tenantId);}
 @PostMapping("/{id}/payment-confirmed") @ResponseStatus(HttpStatus.NO_CONTENT) public void confirmed(@PathVariable UUID id,@RequestHeader(value="X-Internal-API-Key",required=false)String provided,@RequestHeader("X-Tenant-Id")UUID tenant,@RequestHeader("X-Payment-Id")UUID payment){paymentAuth(provided);service.confirmFromPayment(id,tenant,payment);}
 @PostMapping("/{id}/payment-failed") @ResponseStatus(HttpStatus.NO_CONTENT) public void failed(@PathVariable UUID id,@RequestHeader(value="X-Internal-API-Key",required=false)String provided,@RequestHeader("X-Tenant-Id")UUID tenant){paymentAuth(provided);service.failFromPayment(id,tenant);}
 private void auth(String p){auth(p,key);} private void paymentAuth(String p){auth(p,paymentKey);} private void auth(String p,byte[] expected){if(p==null||!MessageDigest.isEqual(expected,p.getBytes(StandardCharsets.UTF_8)))throw new org.springframework.web.server.ResponseStatusException(HttpStatus.UNAUTHORIZED,"Invalid internal credentials");}
 public record PaymentDetails(UUID orderId,UUID tenantId,UUID userId,UUID eventId,int quantity,String status,java.math.BigDecimal amount,String currency,String reference){}
 public record Expired(UUID id,UUID tenantId,java.time.Instant expiresAt){}
}
